const genericPoseNamePattern = /^(和顺古镇)?(和顺|银塔|腾冲|长城|泰装|银杏|草地|树林|森林|海边|竹林|果园|礁石|运动风|大树|外滩|东方明珠|荷花|荷塘|油菜花|野花|橘子洲头|橘洲头|长沙|雕塑)姿势\d+$/

const poseActionNameOverrides = {
}

const buildPoseActionOverride = (pairId, metadata = {}) => {
  const name = poseActionNameOverrides[pairId]

  if (!name) return null

  const sceneName = metadata.landmarkName || metadata.cityName || metadata.categoryName || '场景'
  const badge = metadata.badge || '全身'
  const override = { name }

  if (!metadata.tip) {
    override.tip = `推荐${sceneName}、${name}、景点旅行打卡${badge}照片`
  }

  if (!metadata.description) {
    override.description = `人物在${sceneName}场景中完成“${name}”动作。拍摄时保留环境特征，让姿态、手部动作和背景同时入镜，适合作为${sceneName}专题里的${badge}旅行打卡参考。`
  }

  return override
}

