const getPoseSearchKeywords = (pairId) => [
  ...(poseSearchKeywordOverrides[pairId] || []),
  ...(poseSceneKeywordOverrides[pairId] || [])
].filter((keyword) => !genericPoseNamePattern.test(keyword))

const getPoseStrictSearchKeywords = (pairId) => (
  poseSearchKeywordOverrides[pairId] || []
).filter((keyword) => !genericPoseNamePattern.test(keyword))

const combinePairPoses = combinePairIds.map((pairId, index) => {
  const folder = pairId.split('_')[0]
  const poseNumber = Number(folder.replace('custom', '')) || index + 1
  const metadata = poseMetadataOverrides[pairId] || {}
  const actionNameOverride = buildPoseActionOverride(pairId, metadata)

  return {
    id: `pair-${pairId.replace(/_/g, '-')}`,
    categoryId: 'model-pairs',
    categoryName: '真人示例',
    name: `真人姿势 ${String(poseNumber).padStart(2, '0')}`,
    tip: '先看真人示意，进入相机后按轮廓对齐',
    description: '选择页展示真人模特照片；进入相机后显示对应透明轮廓，用于对齐姿势和构图。',
    badge: '真人',
    accent: '#f4f7ff',
    gradient: 'linear-gradient(150deg, #f7f1e8 0%, #6f665f 100%)',
    guideImage: `/static/pose_pairs/${folder}/${pairId}_contour.png`,
    thumbnailImage: `/static/pose_thumbs/${folder}/${pairId}_thumb.jpg`,
    shareImage: `/static/share_images/${folder}/${pairId}_share.jpg`,
    modelImage: `/static/pose_pairs/${folder}/${pairId}_demo.jpg`,
    detailImage: `/static/pose_pairs/${folder}/${pairId}_demo.jpg`,
    thumbnailMode: 'aspectFill',
    parts: [],
    ...metadata,
    ...actionNameOverride,
    searchKeywords: getPoseSearchKeywords(pairId),
    strictSearchKeywords: getPoseStrictSearchKeywords(pairId)
  }
})

module.exports = {
  combinePairPoses
}
